document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function s(n,e,s,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${s}</div>\n      </div>\n    `}const i=document.getElementById("plumbing-form"),a=document.getElementById("plumbing-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const t=parseFloat(document.getElementById("tools-cost").value),r=parseFloat(document.getElementById("vehicle-cost").value),o=parseFloat(document.getElementById("licenses-insurance").value),l=parseFloat(document.getElementById("working-capital").value),c=parseFloat(document.getElementById("working-days").value),d=parseFloat(document.getElementById("calls-per-day").value),p=parseFloat(document.getElementById("avg-call-price").value),v=parseFloat(document.getElementById("materials-markup").value),u=parseFloat(document.getElementById("fuel-costs").value),g=parseFloat(document.getElementById("materials-cost").value),m=parseFloat(document.getElementById("marketing-costs").value),b=parseFloat(document.getElementById("other-expenses").value);if(c<=0||d<=0||p<=0)return a.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const $=t+r+o+l,w=c*d,f=w*p,h=g*(1+v/100),y=h-g,k=f+h,M=u+g+m+b,E=f+y-(u+m+b),F=12*E,B=E/k*100,I=$/F,P=F/$*100,S=p,x=E/w,D=k/c;let C="info";E<0?C="warning":B>40&&(C="success");let L="info";P<25?L="warning":P>50&&(L="success");let R="info";I>2?R="warning":I<=1&&(R="success"),a.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🔧 Plumbing & Home Repairs Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${s("💰 Total Investment",n($),"Initial capital required","info")}\n            ${s("📈 Monthly Profit",n(E),`Margin: ${e(B)}`,C)}\n            ${s("⏱️ Payback Period",`${I.toFixed(1)} years`,`ROI: ${e(P)}`,R)}\n            ${s("🔧 Service Calls",`${w} per month`,`${n(x)} profit/call`,"info")}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Professional tools & equipment</span>\n                  <span>${n(t)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Service vehicle & equipment</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses & insurance</span>\n                  <span>${n(o)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Working capital</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n($)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Service revenue (${w} calls × ${n(p)})</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Materials sales (${e(v)} markup)</span>\n                  <span>${n(h)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Materials profit</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Fuel & transportation</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Materials & parts (cost basis)</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & advertising</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(M)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Work Efficiency</h6>\n              <div class="metric-subtitle">\n                Calls per day: <strong>${d}</strong><br>\n                Daily revenue: <strong>${n(D)}</strong><br>\n                Revenue per call: <strong>${n(S)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${v>=100?"success":"info"}">\n              <h6>📊 Revenue Structure</h6>\n              <div class="metric-subtitle">\n                Service revenue: <strong>${e(f/k*100)}</strong><br>\n                Materials revenue: <strong>${e(h/k*100)}</strong><br>\n                Materials markup: <strong>${e(v)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${E>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(F)}</strong><br>\n                Weekly profit: <strong>${n(F/52)}</strong><br>\n                Daily profit: <strong>${n(F/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Scaling Potential</h6>\n              <div class="metric-subtitle">\n                With +2 calls/day: <strong>${n(E+2*c*x)}/month</strong><br>\n                With assistant: <strong>${n(1.8*E-2500)}/month</strong><br>\n                Emergency calls (+50%): <strong>${n(1.5*E)}/month</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${B<25?"<li>⚠️ Low profitability. Consider increasing rates or reducing operational costs.</li>":""}\n              ${d<3?"<li>📍 Low call volume. Improve marketing and online presence.</li>":""}\n              ${I>2?"<li>⏰ Long payback period. Optimize startup costs or increase pricing.</li>":""}\n              ${d>6?"<li>✅ High workload! Consider hiring help or increasing rates.</li>":""}\n              ${B>40?"<li>🎉 Excellent profitability! Scale your business and expand services.</li>":""}\n              <li>📱 Build strong online presence: website, social media, Google My Business.</li>\n              <li>🚨 Offer 24/7 emergency services for 30-50% premium pricing.</li>\n              <li>🤝 Develop partnerships with property management companies.</li>\n              <li>⭐ Focus on customer reviews and referral programs.</li>\n              <li>🛠️ Invest in professional equipment for complex, high-value jobs.</li>\n              <li>📚 Expand services: electrical, tile work, HVAC diagnostics.</li>\n              <li>💳 Accept digital payments for customer convenience.</li>\n              <li>📊 Track job types and focus on most profitable services.</li>\n              <li>🎯 Specialize in specific areas for premium pricing opportunities.</li>\n              <li>📋 Offer maintenance contracts for steady recurring revenue.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.plumbingBusinessData={"Total Investment ($)":$,"Monthly Revenue ($)":k,"Monthly Expenses ($)":M,"Monthly Profit ($)":E,"Annual Profit ($)":F,"Profit Margin (%)":B,"Annual ROI (%)":P,"Payback Period (years)":I,"Monthly Service Calls":w,"Average Call Price ($)":p,"Profit per Call ($)":x,"Working Days":c,"Materials Markup (%)":v}}),window.downloadCSV=function(){if(!window.plumbingBusinessData)return;const n=Object.entries(window.plumbingBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),s=document.createElement("a");s.href=URL.createObjectURL(e),s.download="plumbing-business-plan.csv",s.click()}});